export const pillars: PillarPage[] = [
  stickerGuidePillar,
  flyerGuidePillar,
  packagingGuidePillar,
];

export const clusters: ClusterArticle[] = [
  stickerMaterialsCluster,
  stickerPackagingDesignCluster,
  clearVsMatteStickersCluster,
  flyerSizesComparedCluster,
  flyerDistributionStrategyCluster,
  foilFlyersIndustryCluster,
  rigidVsFoldingBoxesCluster,
  ecoPaperBagGsmCluster,
  packagingColorPsychologyCluster,
];

/** 根據 slug 查找支柱頁 */
export function getPillarBySlug(slug: string): PillarPage | undefined {
  return pillars.find(p => p.slug === slug);
}

/** 根據 slug 查找集群文章 */
export function getClusterBySlug(slug: string): ClusterArticle | undefined {
  return clusters.find(c => c.slug === slug);
}

/** 根據支柱 slug 查找下屬集群文章 */
export function getClustersByPillarSlug(pillarSlug: string): ClusterArticle[] {
  return clusters.filter(c => c.pillarSlug === pillarSlug);
}

/** 取得所有 pillar slugs */
export function getAllPillarSlugs(): string[] {
  return pillars.map(p => p.slug);
}

/** 取得所有 cluster slugs */
export function getAllClusterSlugs(): string[] {
  return clusters.map(c => c.slug);
}
